class Solution {
public:
    std::vector<std::vector<int>> permute(int n) {
        std::vector<std::vector<int>> ans;
        std::vector<int> curr;
        std::vector<bool> vis(n + 1, false);

        auto backtrack = [&](auto&& self) -> void {
            if ((int)curr.size() == n) {
                ans.push_back(curr);
                return;
            }
            for (int x = 1; x <= n; ++x) {
                if (!vis[x]) {
                    if (curr.empty() || curr.back() % 2 != x % 2) {
                        vis[x] = true;
                        curr.push_back(x);
                        self(self);
                        curr.pop_back();
                        vis[x] = false;
                    }
                }
            }
        };

        backtrack(backtrack);
        return ans;
    }
};

import java.util.*;

class Solution {
    public List<List<Integer>> permute(int n) {
        List<List<Integer>> ans = new ArrayList<>();
        List<Integer> curr = new ArrayList<>();
        boolean[] vis = new boolean[n + 1];
        backtrack(n, curr, vis, ans);
        return ans;
    }

    private void backtrack(int n, List<Integer> curr, boolean[] vis, List<List<Integer>> ans) {
        if (curr.size() == n) {
            ans.add(new ArrayList<>(curr));
            return;
        }
        for (int x = 1; x <= n; x++) {
            if (!vis[x]) {
                if (curr.isEmpty() || curr.get(curr.size() - 1) % 2 != x % 2) {
                    vis[x] = true;
                    curr.add(x);
                    backtrack(n, curr, vis, ans);
                    curr.remove(curr.size() - 1);
                    vis[x] = false;
                }
            }
        }
    }
}

var permute = function(n) {
    const ans = [];
    const curr = [];
    const vis = new Uint8Array(n + 1);

    function backtrack() {
        if (curr.length === n) {
            ans.push([...curr]);
            return;
        }
        for (let x = 1; x <= n; x++) {
            if (!vis[x]) {
                if (curr.length === 0 || curr[curr.length - 1] % 2 !== x % 2) {
                    vis[x] = 1;
                    curr.push(x);
                    backtrack();
                    curr.pop();
                    vis[x] = 0;
                }
            }
        }
    }

    backtrack();
    return ans;
};
